<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50 pb-safe">
		<!-- ============ HEADER ============ -->
		<div
			ref="headerRef"
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'MasterKaryawan' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali ke Master Karyawan"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>

				<div class="flex min-w-0 flex-1 flex-col justify-center gap-1">
					<nav class="hidden min-w-0 items-center gap-1.5 text-sm md:flex">
						<RouterLink
							:to="{ name: 'MasterKaryawan' }"
							class="text-ui-ink-gray-500 hover:text-ui-ink-gray-700 hover:underline"
						>
							Master Karyawan
						</RouterLink>
						<span class="text-ui-ink-gray-300">/</span>
						<span class="truncate font-medium text-ui-ink-gray-900">{{ judul }}</span>
					</nav>
					<span class="min-w-0 truncate font-medium text-ui-ink-gray-900 md:hidden">{{
						judul
					}}</span>
					<span
						v-if="status"
						class="w-fit shrink-0 rounded-full px-2.5 py-0.5 text-base font-medium leading-snug"
						:class="statusPill(status)"
					>
						{{ status }}
					</span>
				</div>

				<!-- Edit (ikon) tampil bila user boleh mengedit & belum mengedit —
				     sama dengan Data Pengajuan. Tombol Save ada di bar bawah. -->
				<div class="shrink-0">
					<button
						v-if="formRef && !formRef.editMode && formRef.canEditDoc"
						type="button"
						class="flex h-10 w-10 items-center justify-center rounded-lg border border-ui-line-gray-300 bg-ui-surface text-ui-ink-gray-700 transition hover:bg-ui-surface-gray-50 active:bg-ui-surface-gray-100"
						aria-label="Edit"
						title="Edit"
						@click="formRef.enterEditMode()"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-5 w-5"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M12 20h9" />
							<path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z" />
						</svg>
					</button>
				</div>
			</div>
		</div>

		<!-- ============ KONTEN ============ -->
		<!-- Seluruh isi dirender dari meta doctype oleh MetaDocForm: section,
		     tabel anak, dan baris tabel bisa di-collapse bercabang; HR yang punya
		     izin tulis bisa langsung mengubah datanya. -->
		<MetaDocForm
			ref="formRef"
			:doctype="DOCTYPE"
			:name="name"
			:sticky-top="tabTop"
			class="flex-1"
			@loaded="onDoc"
			@saved="onDoc"
		/>
	</div>
</template>

<script setup>
/**
 * Detail Master Karyawan — lihat & ubah, sepenuhnya dari metadata doctype.
 * Tidak ada nama field yang ditulis di sini selain judul & status di header.
 */
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import MetaDocForm from '../components/MetaDocForm.vue'

const DOCTYPE = 'Master Karyawan'
const route = useRoute()
const name = computed(() => route.params.name)

const formRef = ref(null)
const data = ref(null)
function onDoc(doc) {
	data.value = doc
}
const judul = computed(() => data.value?.employee_name || name.value)
// Field status Master Karyawan = `status_karyawan` (kolom `status` lama yatim).
const status = computed(() => data.value?.status_karyawan || '')

const STATUS_PILL = {
	Active: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	Inactive: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	Suspended: 'bg-ui-surface-amber-100 text-ui-ink-amber-700',
	Left: 'bg-ui-surface-red-100 text-ui-ink-red-700',
}
function statusPill(s) {
	return STATUS_PILL[s] || 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
}

// ---- Offset sticky tab strip (tepat di bawah header) ------------------------
const headerRef = ref(null)
const tabTop = ref(0)
function ukur() {
	tabTop.value = Math.max(0, (headerRef.value?.offsetHeight || 0) - 1)
}
let ro = null
onMounted(() => {
	nextTick(ukur)
	if (typeof ResizeObserver !== 'undefined' && headerRef.value) {
		ro = new ResizeObserver(ukur)
		ro.observe(headerRef.value)
	}
	window.addEventListener('resize', ukur)
})
onBeforeUnmount(() => {
	ro?.disconnect()
	window.removeEventListener('resize', ukur)
})
</script>
